import numpy as np
import matplotlib.pyplot as plt 

# https://jakevdp.github.io/blog/2013/12/05/static-interactive-widgets/
# https://www.eg.bucknell.edu/~brk009/notebook-on-wp/

def update(frameNum, img, grid, N, direction):
    newGrid = grid.copy()
    for i in range(N):
        for j in range(N):
            # compute 8-neghbor sum using toroidal boundary conditions
            total = int((grid[i, (j-1)%N] + grid[i, (j+1)%N] + 
                         grid[(i-1)%N, j] + grid[(i+1)%N, j] + 
                         grid[(i-1)%N, (j-1)%N] + grid[(i-1)%N, (j+1)%N] + 
                         grid[(i+1)%N, (j-1)%N] + grid[(i+1)%N, (j+1)%N])/255)
            # apply Conway's rules
            if grid[i, j]  == 255:
                if (total < 2) or (total > 3):
                    newGrid[i, j] = 0
            else:
                if total == 3:
                    newGrid[i, j] = 255
    
    if direction == "up":
        for i in range(N):
            if i == N-1:
                newGrid[N-1] = [0] * N
            else:
                if 255 in newGrid[i+1] or 255 in newGrid[i]:
                    newGrid[i] = newGrid[i+1]

    if direction == "left":
        temp = newGrid.transpose()
        for i in range(N):
            if i == N-1:
                temp[N-1] = [0] * N
            else:
                if 255 in temp[i+1] or 255 in temp[i]:
                    temp[i] = temp[i+1]
        newGrid = temp.transpose()

    if direction == "down":
        for i in reversed(range(N)):
            if i == N-1:
                newGrid[0] = [0] * N
            else:
                if 255 in newGrid[i-1] or 255 in newGrid[i]:
                    newGrid[i] = newGrid[i-1]

    if direction == "right":
        temp = newGrid.transpose()
        for i in reversed(range(N)):
            if i == N-1:
                temp[0] = [0] * N
            else:
                if 255 in temp[i-1] or 255 in temp[i]:
                    temp[i] = temp[i-1]
        newGrid = temp.transpose()

    if direction == "p":
        # printGrid = newGrid.reshape(N, N).tobytes()
        # print(printGrid)
        print(np.frombuffer(newGrid, dtype=newGrid.dtype).reshape(N, N))
        # with open("out.txt", "w") as output:
        #     output.write(printGrid)

    # update data
    img.set_data(newGrid)
    grid[:] = newGrid[:]

    return img,

def on_key(event):
    if event.key in ["left","right","up","down","p"]:
        update(1, img, grid, 111, event.key)
        fig.canvas.draw()
    
